1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	const STDIN = 0;
5	
6	/**
7	 * Reading, parsing and running all fail the same way from the outside: the
8	 * scenario cannot be settled, so the office reports why and nothing is paid.
9	 * Only the message is printed — a stack trace is a crash report, not a
10	 * description of what was wrong with the input.
11	 */
12	try {
13	  const scenario = JSON.parse(readFileSync(STDIN, "utf8")) as Scenario;
14	  process.stdout.write(JSON.stringify(runScenario(scenario)));
15	} catch (error) {
16	  const description = error instanceof Error ? error.message : String(error);
17	  process.stderr.write(`${description}\n`);
18	  process.exit(1);
19	}
