1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	/**
57	 * Both roundings go the MHPCO's way, and both are applied once, at the very end
58	 * of a calculation — never to an intermediate amount. The two are stated here as
59	 * a pair because that is the rule: it is one policy with two directions, and
60	 * which direction applies follows from who pays.
61	 */
62	const roundedUpForWhatTheCustomerPays = Math.ceil;
63	const roundedDownForWhatTheMHPCOPays = Math.floor;
64	
65	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
68	/**
69	 * Enchantment is read by two unrelated rules with different cut-offs: this one
70	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
71	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
72	 * the two cannot be mistaken for one shared notion of "highly enchanted".
73	 */
74	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
75	const LOYALTY_DISCOUNT_PERCENT = 20;
76	const LOYALTY_THRESHOLD_YEARS = 2;
77	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
78	
79	/**
80	 * Everything the pricing rules need to know about an item type lives here, so
81	 * that "what is a rune?" has a single answer. Components are the small parts
82	 * (runes, moonstones) that can be bought as a building block; main items
83	 * (swords, amulets, ...) never form a block.
84	 */
85	const ITEM_TYPES: Record<
86	  string,
87	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
88	> = {
89	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
90	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
91	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
92	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
93	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
94	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
95	};
96	
97	/**
98	 * The single gate onto ITEM_TYPES, so that an item the MHPCO does not insure is
99	 * refused by name rather than surfacing as a stray TypeError somewhere downstream.
100	 */
101	const itemTypeOf = (type: string): (typeof ITEM_TYPES)[string] => {
102	  const itemType = ITEM_TYPES[type];
103	  if (itemType === undefined) {
104	    throw new Error(`unknown item type: ${type}`);
105	  }
106	  return itemType;
107	};
108	
109	/** A building block of 3 alike components is offered at this base premium. */
110	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
111	const COMPONENT_BLOCK_SIZE = 3;
112	
113	/**
114	 * Tallies how often each value occurs, e.g. ["rune", "rune"] → [["rune", 2]].
115	 *
116	 * Takes plain strings rather than items because both callers are counting a
117	 * type name, but reach it by different routes: a quote counts `item.type`, a
118	 * claim counts `damage.itemType`. Each caller projects its own key and this
119	 * stays ignorant of what the strings denote.
120	 */
121	const tally = (values: string[]): [string, number][] => {
122	  const counts = new Map<string, number>();
123	  for (const value of values) {
124	    counts.set(value, (counts.get(value) ?? 0) + 1);
125	  }
126	  return [...counts];
127	};
128	
129	/**
130	 * The two projections `tally` is fed. Named as a pair because their results are
131	 * compared against each other: a claim is covered when the damaged type names
132	 * line up with the insured ones, and that comparison only reads as a comparison
133	 * if both sides are reached the same way.
134	 */
135	const typesOf = (items: Item[]): string[] => items.map((item) => item.type);
136	
137	const damagedTypesOf = (damages: Damage[]): string[] =>
138	  damages.map((damage) => damage.itemType);
139	
140	/**
141	 * Prices every item of one type together, because exactly 3 alike components
142	 * form a block charged as one. "Alike" means the same type, and the block does
143	 * not repeat: 4 or 7 runes are each priced per item.
144	 */
145	const basePremiumForType = (type: string, count: number): number => {
146	  const { unitPremium, isComponent } = itemTypeOf(type);
147	  return isComponent && count === COMPONENT_BLOCK_SIZE
148	    ? COMPONENT_BLOCK_BASE_PREMIUM
149	    : count * unitPremium;
150	};
151	
152	const sumOfBasePremiums = (items: Item[]): number =>
153	  tally(typesOf(items)).reduce(
154	    (sum, [type, count]) => sum + basePremiumForType(type, count),
155	    0,
156	  );
157	
158	/**
159	 * A rule whose rate is ADDED to those of every other matching rule. Read with
160	 * filter+reduce: matching several rules charges for each.
161	 *
162	 * Distinct from ExclusiveRule<T> below, which has the same {appliesTo, rate}
163	 * shape but the opposite semantics. The two are separate named types rather
164	 * than one shared shape so that the reader — and the compiler — cannot mistake
165	 * a stacking table for a first-match-wins one.
166	 */
167	interface StackingRule<T> {
168	  appliesTo: (subject: T) => boolean;
169	  rate: number;
170	}
171	
172	/**
173	 * What a stacking table charges against a base amount: every matching rule
174	 * contributes, so the rates add up rather than compete. This is the one place
175	 * the filter+reduce reading of StackingRule is performed — item surcharges and
176	 * policy adjustments are both this same idea, differing only in which table
177	 * they consult and what their percentages are taken of.
178	 */
179	const sumOfMatchingRates = <T>(
180	  rules: StackingRule<T>[],
181	  subject: T,
182	  base: number,
183	): number =>
184	  rules
185	    .filter(({ appliesTo }) => appliesTo(subject))
186	    .reduce((sum, { rate }) => sum + percent(base, rate), 0);
187	
188	/**
189	 * A rule that is an ALTERNATIVE to the others: the first match wins and the
190	 * rest are skipped. Read with find. Order is therefore meaningful — it encodes
191	 * precedence, and reordering the table changes results.
192	 */
193	interface ExclusiveRule<T> {
194	  appliesTo: (subject: T) => boolean;
195	  rate: number;
196	}
197	
198	/**
199	 * Item-specific modifiers: each applies to one item and is charged as a
200	 * percentage of THAT item's unit premium, never of the policy total.
201	 * They stack — an item matching several rules is charged for each.
202	 *
203	 * Unit premium, not the item's share of the policy base: the two differ only
204	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
205	 * no test pins down a surcharged component yet. Revisit when one does.
206	 */
207	const ITEM_MODIFIERS: StackingRule<Item>[] = [
208	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
209	  {
210	    appliesTo: (item) =>
211	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
212	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
213	  },
214	];
215	
216	const surchargeForItem = (item: Item): number =>
217	  sumOfMatchingRates(ITEM_MODIFIERS, item, itemTypeOf(item.type).unitPremium);
218	
219	const sumOfItemSurcharges = (items: Item[]): number =>
220	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
221	
222	/**
223	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
224	 * premium (the sum of item base premiums, before any item surcharge), so no
225	 * modifier is ever computed on top of another. Discounts carry a negative rate.
226	 */
227	interface PolicyContext {
228	  customer: Customer;
229	  /** Quotes already issued to this customer earlier in the scenario. */
230	  previousContracts: number;
231	}
232	
233	const POLICY_MODIFIERS: StackingRule<PolicyContext>[] = [
234	  // Always applies: every item in a quote is treated as a first insurance,
235	  // regardless of how long the customer has been with the MHPCO.
236	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
237	  {
238	    // Negative rate: a discount is just a surcharge pointing the other way, so
239	    // it needs no separate code path and cannot stack onto another modifier.
240	    appliesTo: ({ customer }) =>
241	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
242	    rate: -LOYALTY_DISCOUNT_PERCENT,
243	  },
244	  {
245	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
246	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
247	  },
248	];
249	
250	const sumOfPolicyAdjustments = (
251	  context: PolicyContext,
252	  policyBasePremium: number,
253	): number =>
254	  sumOfMatchingRates(POLICY_MODIFIERS, context, policyBasePremium);
255	
256	const premiumFor = (context: PolicyContext, items: Item[]): number => {
257	  const policyBasePremium = sumOfBasePremiums(items);
258	  return roundedUpForWhatTheCustomerPays(
259	    policyBasePremium +
260	      sumOfItemSurcharges(items) +
261	      sumOfPolicyAdjustments(context, policyBasePremium) +
262	      PROCESSING_FEE,
263	  );
264	};
265	
266	/** A policy created by a quote step, tracked so later claims can draw on it. */
267	interface Policy {
268	  items: Item[];
269	  remainingCap: number;
270	}
271	
272	const DEDUCTIBLE_PER_DAMAGE = 100;
273	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
274	
275	const insuranceSumOf = (items: Item[]): number =>
276	  items.reduce((sum, item) => sum + itemTypeOf(item.type).insuranceValue, 0);
277	
278	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
279	const REDUCED_REIMBURSEMENT_PERCENT = 50;
280	
281	/** Reimbursed in full when no clause below claims the item. */
282	const FULL_REIMBURSEMENT_PERCENT = 100;
283	const DRAGON_MATERIAL = "dragon";
284	
285	/**
286	 * Clauses that change how much of a damage is reimbursed. Exclusive and ordered
287	 * by precedence, because clauses overlap (a highly enchanted dragon-material
288	 * item matches more than one) and they are alternatives — unlike the stacking
289	 * ITEM_MODIFIERS, which the {appliesTo, rate} shape would otherwise suggest.
290	 */
291	const REIMBURSEMENT_CLAUSES: ExclusiveRule<Item>[] = [
292	  {
293	    appliesTo: (item) =>
294	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
295	    rate: REDUCED_REIMBURSEMENT_PERCENT,
296	  },
297	  // Listed after the clause above so that a highly enchanted dragon item is
298	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
299	  // default yields, so removing it would not change any current result — it is
300	  // here because the spec states dragon material as a rule, and because the
301	  // ordering is what makes the 50 % rule win.
302	  {
303	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
304	    rate: FULL_REIMBURSEMENT_PERCENT,
305	  },
306	];
307	
308	const reimbursementRateFor = (item: Item): number =>
309	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
310	  FULL_REIMBURSEMENT_PERCENT;
311	
312	/**
313	 * The one phrasing of "the policy does not cover that". Both the whole-claim
314	 * check and the per-damage lookup below can raise it, so the wording lives in
315	 * one place rather than being written out at each site.
316	 *
317	 * A damage naming a type the MHPCO does not insure at all is this same refusal:
318	 * it is not in the policy either, so it needs no rule of its own.
319	 */
320	const notCoveredByPolicy = (itemType: string): Error =>
321	  new Error(`damaged item is not covered by the policy: ${itemType}`);
322	
323	/**
324	 * Which insured item a damage entry is about. The counterpart to itemTypeOf:
325	 * both resolve a name to the thing it denotes.
326	 *
327	 * The not-found branch is unreachable for any damage that got past
328	 * assertDamagesAreCovered, which rejects uncovered types before a payout is
329	 * computed. It stays because `find` returns `Item | undefined` and the type has
330	 * to be honoured — but the rule it enforces is stated there, not here, so this
331	 * reuses that refusal instead of restating it.
332	 */
333	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
334	  const insuredItem = insuredItems.find(
335	    (item) => item.type === damage.itemType,
336	  );
337	  if (insuredItem === undefined) {
338	    throw notCoveredByPolicy(damage.itemType);
339	  }
340	  return insuredItem;
341	};
342	
343	/**
344	 * The clause is applied to the damage first; the deductible comes off whatever
345	 * the clause leaves.
346	 *
347	 * Takes the already-resolved item, so this is pure arithmetic over a damage and
348	 * the item it hit — mirroring basePremiumForType, which likewise prices an
349	 * already-resolved type rather than doing its own lookup.
350	 */
351	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
352	  percent(damage.amount, reimbursementRateFor(damagedItem)) -
353	  DEDUCTIBLE_PER_DAMAGE;
354	
355	/**
356	 * The contract a quote step issues: what it covers, and how much of its cap is
357	 * still available to later claims.
358	 */
359	const policyFor = (items: Item[]): Policy => ({
360	  items,
361	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
362	});
363	
364	/**
365	 * What an incident is worth against a policy, as a pure calculation: each
366	 * damage is settled on its own (own clause, own deductible) and the results are
367	 * added up. Drawing this down from the policy's cap is the caller's job.
368	 */
369	const payoutForIncident = (
370	  incident: ClaimStep["incident"],
371	  insuredItems: Item[],
372	): number =>
373	  incident.damages.reduce(
374	    (sum, damage) =>
375	      sum + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
376	    0,
377	  );
378	
379	/**
380	 * A policy covering one sword cannot answer for two damaged swords. Checked
381	 * before anything is paid, because the whole claim is rejected rather than
382	 * settled as far as the cover reaches.
383	 */
384	const assertDamagesAreCovered = (
385	  damages: Damage[],
386	  insuredItems: Item[],
387	): void => {
388	  const insuredCounts = new Map(tally(typesOf(insuredItems)));
389	  for (const [itemType, damaged] of tally(damagedTypesOf(damages))) {
390	    const insured = insuredCounts.get(itemType) ?? 0;
391	    if (insured === 0) {
392	      throw notCoveredByPolicy(itemType);
393	    }
394	    if (damaged > insured) {
395	      throw new Error(`more ${itemType} damages than the policy covers`);
396	    }
397	  }
398	};
399	
400	/**
401	 * A negative damage would be a negative payout, which the drawdown would then
402	 * SUBTRACT from the remaining cap — letting a claim enlarge the very cover it
403	 * draws on. Refused outright rather than clamped to zero.
404	 *
405	 * Not-negative rather than strictly positive: a zero damage is harmless — it
406	 * pays nothing and moves no cap — so there is no rule to enforce against it.
407	 */
408	const assertDamageAmountsAreNotNegative = (damages: Damage[]): void => {
409	  for (const { amount } of damages) {
410	    if (amount < 0) {
411	      throw new Error(`negative damage amount: ${amount}`);
412	    }
413	  }
414	};
415	
416	/**
417	 * Settles an incident against a policy and draws the payout down from its cap.
418	 * Mutates the policy, because what this claim consumes has to be visible to
419	 * every later claim on the same one.
420	 *
421	 * Both assertions run before any payout is computed, because a bad claim is
422	 * refused whole rather than settled as far as it is valid.
423	 *
424	 * The cap is a ceiling, not just a running total: once it is exhausted a claim
425	 * is paid only what is left of it. Rounding happens once, here, after the clamp
426	 * — so per-damage amounts stay fractional (a multi-item incident is not rounded
427	 * once per damage) and the cap stays whole.
428	 */
429	const settleClaim = (
430	  policy: Policy,
431	  incident: ClaimStep["incident"],
432	): StepResult => {
433	  assertDamageAmountsAreNotNegative(incident.damages);
434	  assertDamagesAreCovered(incident.damages, policy.items);
435	  const payout = roundedDownForWhatTheMHPCOPays(
436	    Math.min(payoutForIncident(incident, policy.items), policy.remainingCap),
437	  );
438	  policy.remainingCap -= payout;
439	  return { payout, remainingCap: policy.remainingCap };
440	};
441	
442	/**
443	 * Steps are executed in order because a step's result can depend on the ones
444	 * before it: the count of contracts already issued decides the follow-up
445	 * discount, and the policies a quote registers are what later claims draw on.
446	 */
447	export const runScenario = (scenario: Scenario): ScenarioResult => {
448	  let previousContracts = 0;
449	  const policies = new Map<number, Policy>();
450	
451	  const results = scenario.steps.map((step, index): StepResult => {
452	    if (step.op === "claim") {
453	      // Unguarded: no test yet describes a claim naming a policy that was never
454	      // quoted. The "claim references an item/policy not in the policy" test
455	      // will force this honest.
456	      const policy = policies.get(step.policy) as Policy;
457	      return settleClaim(policy, step.incident);
458	    }
459	
460	    const premium = premiumFor(
461	      { customer: scenario.customer, previousContracts },
462	      step.items,
463	    );
464	    policies.set(index, policyFor(step.items));
465	    // Counted after pricing, so a quote never discounts itself, and only for
466	    // quotes, because a claim does not issue a contract.
467	    previousContracts += 1;
468	    return { premium };
469	  });
470	  return { results };
471	};
